+const filterButtons = Array.from(document.querySelectorAll(".filter-button"));
+const productCards = Array.from(document.querySelectorAll(".product-card"));
+const productStatus = document.getElementById("product-status");
+const countdown = document.getElementById("deal-countdown");
+
+function updateProductFilter(filter) {
+  let visibleCount = 0;
+
+  productCards.forEach((card) => {
+    const matches = filter === "all" || card.dataset.category === filter;
+    card.hidden = !matches;
+
+    if (matches) {
+      visibleCount += 1;
+    }
+  });
+
+  if (productStatus) {
+    const filterLabel = filter === "all" ? "all categories" : filter;
+    productStatus.textContent = `Showing ${visibleCount} featured products for ${filterLabel}.`;
+  }
+}
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedFilter = button.dataset.filter || "all";
+
+    filterButtons.forEach((item) => {
+      const isActive = item === button;
+      item.classList.toggle("is-active", isActive);
+      item.setAttribute("aria-pressed", String(isActive));
+    });
+
+    updateProductFilter(selectedFilter);
+  });
+});
+
+function updateCountdown() {
+  if (!countdown) {
+    return;
+  }
+
+  const now = new Date();
+  const end = new Date(now);
+  end.setHours(24, 0, 0, 0);
+
+  const difference = end.getTime() - now.getTime();
+  const hours = Math.floor(difference / (1000 * 60 * 60));
+  const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
+  const seconds = Math.floor((difference % (1000 * 60)) / 1000);
+
+  countdown.textContent = `${String(hours).padStart(2, "0")}h ${String(minutes).padStart(2, "0")}m ${String(seconds).padStart(2, "0")}s`;
+}
+
+updateProductFilter("all");
+updateCountdown();
+window.setInterval(updateCountdown, 1000);
